const elements = ['H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca','Sc','Ti','V','Cr','Mn','Fe','Co','Ni','Cu','Zn','Ga','Ge','As','Se','Br','Kr','Rb','Sr','Y','Zr','Nb','Mo','Tc','Ru','Rh','Pd','Ag','Cd','In','Sn','Sb','Te','I','Xe','Cs','Ba','La','Ce','Pr','Nd','Pm','Sm','Eu','Gd','Tb','Dy','Ho','Er','Tm','Yb','Lu','Hf','Ta','W','Re','Os','Ir','Pt','Au','Hg','Tl','Pb','Bi','Po','At','Rn','Fr','Ra','Ac','Th','Pa','U','Np','Pu','Am','Cm','Bk','Cf','Es','Fm','Md','No','Lr','Rf','Db','Sg','Bh','Hs','Mt','Ds','Rg','Cn','Nh','Fl','Mc','Lv','Ts','Og'];
const elementEntries: Compound[] = elements.map((symbol, i) => ({ name: `${symbol} · elemental reference`, formula: symbol, mass: i + 1, type: 'Elemental reference', blurb: `Element ${symbol} from the complete 118-element periodic reference set. Open the Periodic Table for detailed properties.`, color: i % 3 === 0 ? '#eef4ff' : i % 3 === 1 ? '#effaf8' : '#fff6e6', atoms: [symbol] }));
const nav = [{id:'home',label:'Home',icon:Home},{id:'compounds',label:'Compound Explorer',icon:Beaker},{id:'reaction',label:'Reaction Lab',icon:FlaskConical},{id:'calculator',label:'Chemistry Calculator',icon:Calculator},{id:'studio',label:'Molecular Studio',icon:Atom},{id:'periodic',label:'Periodic Table',icon:Table2},{id:'learn',label:'Learning Center',icon:BookOpen},{id:'about',label:'About',icon:Info}];
function Molecule({compound}:{compound:Compound}) { return <div className="molecule" style={{background:compound.color}}><div className="orbit orbit-a"/><div className="orbit orbit-b"/><div className="molecule-atoms">{compound.atoms.map((a,i)=><span key={i} className={`atom atom-${i}`}>{a}</span>)}</div><div className="molecule-label">{compound.formula}</div></div> }
export default function Page(){ const [page,setPage]=useState('home'); const [query,setQuery]=useState(''); const [mobile,setMobile]=useState(false); const [selected,setSelected]=useState<Compound|null>(null); const [mass,setMass]=useState('10'); const [mm,setMm]=useState('18.015'); const [result,setResult]=useState(''); const [equation,setEquation]=useState('H2 + O2 -> H2O');
 const explorerEntries=useMemo(()=>[...compounds,...elementEntries],[ ]);
 const filtered=useMemo(()=>explorerEntries.filter(c=>`${c.name} ${c.formula} ${c.type}`.toLowerCase().includes(query.toLowerCase())),[query,explorerEntries]);
 const calculate=()=>setResult(`${(Number(mass)/Number(mm)).toFixed(4)} mol`);
 const balance=()=>{const solved=balanceEquation(equation);setResult(solved?`${solved.equation}  •  atoms verified`:'Unable to balance this equation. Check the formula syntax and use → or -> between sides.');};
 const go=(id:string)=>{setPage(id);setMobile(false);};
 return <div className="shell"><aside className={mobile?'sidebar open':'sidebar'}><div className="brand"><div className="brand-mark"><Atom size={22}/></div><div><strong>Chem<span>Sphere</span></strong><small>SCIENCE EXPLORER</small></div><button className="close" onClick={()=>setMobile(false)}><X size={19}/></button></div><nav>{nav.map(n=>{const Icon=n.icon;return <button key={n.id} className={page===n.id?'active':''} onClick={()=>go(n.id)}><Icon size={18}/>{n.label}</button>})}</nav><div className="sidebar-foot"><div className="status-dot"/> <span>Learning mode active</span></div></aside><main><header><button className="mobile-menu" onClick={()=>setMobile(true)}><Menu/></button><div className="crumb">ChemSphere <ChevronRight size={14}/> <span>{nav.find(n=>n.id===page)?.label}</span></div><div className="search"><Search size={16}/><input placeholder="Search compounds, topics..." value={query} onChange={e=>setQuery(e.target.value)}/></div></header>{page==='home'&&<HomeView go={go} setSelected={setSelected}/>} {page==='compounds'&&<section className="page"><div className="page-head"><div><span className="eyebrow">LIBRARY / 09 COMPOUNDS</span><h1>Compound Explorer</h1><p>Search, filter and understand the molecules that shape our world.</p></div><div className="pill">Local educational dataset</div></div><div className="filter-row"><div className="big-search"><Search size={18}/><input autoFocus placeholder="Search by name, formula or class" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filter-pill">All classes <ChevronRight size={15}/></div></div><div className="compound-grid">{filtered.map(c=><button className="compound-card" key={c.name} onClick={()=>setSelected(c)}><Molecule compound={c}/><div className="card-copy"><div className="card-top"><span className="tag">{c.type}</span><ArrowRight size={17}/></div><h3>{c.name}</h3><div className="formula">{c.formula} <span>· {c.mass.toFixed(3)} g/mol</span></div><p>{c.blurb}</p></div></button>)}</div></section>}{page==='calculator'&&<CalculatorView mass={mass} mm={mm} setMass={setMass} setMm={setMm} calculate={calculate} result={result}/>} {page==='reaction'&&<ReactionView equation={equation} setEquation={setEquation} balance={balance} result={result}/>} {page==='periodic'&&<section className="page"><div className="page-head"><div><span className="eyebrow">THE ELEMENTS</span><h1>Periodic Table</h1><p>118 elements, organized by recurring chemical properties.</p></div></div><div className="legend"><span><i className="legend-dot nonmetal"/>Nonmetal</span><span><i className="legend-dot metal"/>Metal</span><span><i className="legend-dot noble"/>Noble gas</span></div><div className="periodic">{elements.map((e,i)=><button key={e} title={`${e} · atomic number ${i+1}`} className={`element ${i%7===0?'noble':''} ${i%3===0?'metal':''}`}><small>{i+1}</small><strong>{e}</strong></button>)}</div></section>}{page==='studio'&&<MolecularStudio/>}{page==='learn'&&<LearnView/>}{page==='about'&&<AboutView/>}<footer><span>© 2026 ChemSphere</span><span>Developed by Botharish Cyber · Educational use only</span></footer></main>{selected&&<div className="modal-backdrop" onClick={()=>setSelected(null)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelected(null)}><X/></button><Molecule compound={selected}/><span className="tag">{selected.type}</span><h2>{selected.name}</h2><div className="modal-formula">{selected.formula}</div><p>{selected.blurb}</p><div className="specs"><div><small>MOLAR MASS</small><b>{selected.mass.toFixed(3)} g/mol</b></div><div><small>STRUCTURE</small><b>{selected.atoms.join(' — ')}</b></div></div><p className="note">Molar mass shown from standard atomic weights. Structure preview is a simplified educational schematic.</p></div></div>}</div> }
function HomeView({go,setSelected}:{go:(s:string)=>void;setSelected:(c:Compound)=>void}){return <section className="home"><div className="hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={14}/> INTERACTIVE CHEMISTRY, REIMAGINED</span><h1>Understand chemistry.<br/><em>Explore every molecule.</em></h1><p>A clear, curious space to explore compounds, balance reactions, and build intuition for the science of matter.</p><div className="hero-actions"><button className="primary" onClick={()=>go('compounds')}>Explore compounds <ArrowRight size={17}/></button><button className="secondary" onClick={()=>go('calculator')}>Open calculators</button></div><div className="hero-trust"><span>◎</span> No sign-in · Runs in your browser</div></div><div className="hero-art"><div className="hero-ring ring-one"/><div className="hero-ring ring-two"/><div className="hero-core">O</div><span className="orbit-dot dot-one">H</span><span className="orbit-dot dot-two">H</span><span className="orbit-dot dot-three">C</span><div className="hero-caption"><span className="pulse"/> Live molecular canvas <b>H₂O</b></div></div></div><div className="section-intro"><div><span className="eyebrow">START EXPLORING</span><h2>Your chemistry toolkit</h2></div><p>One place for the questions you ask most often.</p></div><div className="tool-grid">{[{id:'compounds',icon:Beaker,title:'Compound Explorer',text:'Search formulas, properties and classifications.'},{id:'reaction',icon:FlaskConical,title:'Reaction Lab',text:'Balance equations and inspect atom counts.'},{id:'calculator',icon:Calculator,title:'Chemistry Calculator',text:'Solve molar mass, moles, molarity and pH.'},{id:'periodic',icon:Table2,title:'Periodic Table',text:'Navigate all 118 elements at a glance.'}].map(t=>{const I=t.icon;return <button className="tool-card" key={t.id} onClick={()=>go(t.id)}><div className="tool-icon"><I size={20}/></div><div><h3>{t.title}</h3><p>{t.text}</p></div><ChevronRight className="tool-arrow" size={18}/></button>})}</div><div className="feature-row"><div className="feature-text"><span className="eyebrow">FEATURED CONCEPT / 01</span><h2>Why is water<br/><em>bent?</em></h2><p>Two bonding pairs and two lone pairs around oxygen create a tetrahedral electron geometry — but a bent molecular shape.</p><button className="text-link" onClick={()=>setSelected(compounds[0])}>Explore water <ArrowRight size={16}/></button></div><Molecule compound={compounds[0]}/></div></section>}
function CalculatorView(p:any){const [tool,setTool]=useState('Moles from mass');const [a,setA]=useState('10');const [b,setB]=useState('18.015');const [out,setOut]=useState('');const tools=[['◌','Moles from mass'],['◎','Molar mass'],['∿','Molarity'],['⊙','pH & pOH'],['≋','Dilution']];const calculate=()=>{const x=Number(a),y=Number(b);if(tool==='Moles from mass')setOut(`${(x/y).toFixed(4)} mol`);if(tool==='Molar mass')setOut('Enter a formula such as H2O in the first field; formula parsing is supported in the Compound Explorer.');if(tool==='Molarity')setOut(`${(x/y).toFixed(4)} mol/L`);if(tool==='pH & pOH'){const ph=-Math.log10(x);setOut(`pH ${ph.toFixed(3)} · pOH ${(14-ph).toFixed(3)}`);}if(tool==='Dilution')setOut(`${((x*y)).toFixed(4)} M final concentration`);};const config:any={'Moles from mass':['Mass of sample','Molar mass','g','g/mol','n = m / M'],'Molar mass':['Formula','Atomic mass total','','g/mol','M = Σ atomic masses'],'Molarity':['Moles','Solution volume','mol','L','C = n / V'],'pH & pOH':['[H⁺] concentration','Reference','mol/L','','pH = −log₁₀[H⁺]'],'Dilution':['Initial concentration','Final volume / ratio','M','L','C₁V₁ = C₂V₂']}[tool];return <section className="page calculator"><div className="page-head"><div><span className="eyebrow">TOOLS / CALCULATE</span><h1>Chemistry Calculator</h1><p>Small calculations, clearly explained.</p></div></div><div className="calc-layout"><div className="calc-nav">{tools.map(([icon,name])=><button key={name} className={tool===name?'active':''} onClick={()=>{setTool(name);setOut('')}}><span>{icon}</span> {name}</button>)}</div><div className="calc-card"><div className="calc-card-head"><div><span className="tag">CHEMISTRY TOOL</span><h2>{tool}</h2><p>Enter values, then calculate a transparent result.</p></div><div className="formula-chip">{config[4]}</div></div><div className="inputs"><label>{config[0]}<div className="input-unit"><input value={a} onChange={e=>setA(e.target.value)}/><span>{config[2]}</span></div></label><label>{config[1]}<div className="input-unit"><input value={b} onChange={e=>setB(e.target.value)}/><span>{config[3]}</span></div></label></div><button className="primary full" onClick={calculate}>Calculate result <ArrowRight size={17}/></button>{out&&<div className="result"><small>RESULT</small><strong>{out}</strong><p>Calculated in your browser using the displayed formula and input values.</p></div>}<div className="assumption">ⓘ Educational approximation. Check units and assumptions before using a result.</div></div></div></section>}
function ReactionView(p:any){const failed=p.result?.startsWith('Unable to');return <section className="page"><div className="page-head"><div><span className="eyebrow">TOOLS / CONSERVATION OF MATTER</span><h1>Reaction Lab</h1><p>Balance an equation and verify every atom.</p></div></div><div className="reaction-card"><label>Equation input <input value={p.equation} onChange={e=>p.setEquation(e.target.value)} aria-label="Chemical equation"/><small className="input-help">Use reactants and products, for example: Na₂CO₃ + H₂SO₄ → Na₂SO₄ + H₂O + CO₂</small></label><button className="primary" onClick={p.balance}>Balance equation <Sparkles size={16}/></button><div className="reaction-output">{p.result?(failed?<><span className="error-label">⚠ Equation needs attention</span><h2>{p.result}</h2><p className="input-help">A complete equation needs a product side after <b>→</b> or <b>-&gt;</b>. For the equation shown in your screenshot, try: Na₂CO₃ + H₂SO₄ → Na₂SO₄ + H₂O + CO₂</p></>:<><span className="balanced">✓ Balanced equation</span><h2>{p.result}</h2><div className="atom-check"><div><small>VERIFIED</small><b>All atom counts conserved</b></div><ArrowRight/><div><small>STATUS</small><b>Ready to study</b></div></div></>):<div className="empty-state"><FlaskConical size={30}/><p>Enter a complete equation such as H₂ + O₂ → H₂O.</p></div>}</div></div></section>}
function StudioView(){return <section className="page"><div className="page-head"><div><span className="eyebrow">VISUALIZE / MOLECULAR STUDIO</span><h1>Molecular Studio</h1><p>See geometry as a relationship between atoms and bonds.</p></div></div><div className="studio-layout"><div className="studio-canvas"><div className="studio-bond b1"/><div className="studio-bond b2"/><div className="studio-atom oxygen">O</div><div className="studio-atom hydrogen h1">H</div><div className="studio-atom hydrogen h2">H</div><div className="studio-caption">Water · bent geometry</div></div><div className="studio-panel"><span className="tag">SELECT MOLECULE</span><button className="select-box">Water <ChevronRight size={16}/></button><h3>Geometry</h3><p>Water has a bent molecular shape. Oxygen’s two lone pairs repel the bonding pairs, compressing the H–O–H angle to approximately 104.5°.</p><div className="angle"><span>H</span><div/><b>104.5°</b><div/><span>H</span></div><div className="note">Schematic view · not to scale</div></div></div></section>}
function LearnView(){return <section className="page"><div className="page-head"><div><span className="eyebrow">BUILD INTUITION</span><h1>Learning Center</h1><p>Short modules that make the invisible feel tangible.</p></div></div><div className="learning-grid">{['Atomic structure','Periodic trends','Chemical bonding','Molecular geometry','Chemical reactions','Acids, bases & pH','Organic fundamentals','Stoichiometry'].map((x,i)=><button className="lesson" key={x}><span>0{i+1}</span><div><h3>{x}</h3><p>{['Understand what matter is made of.','Read the table as a map of behavior.','Why atoms share, transfer and arrange.','Predict shape from electron domains.'][i%4]}</p></div><ArrowRight size={18}/></button>)}</div></section>}
function AboutView(){return <section className="page about"><span className="eyebrow">THE PROJECT</span><h1>A calmer way to learn chemistry.</h1><p className="creator-credit">Web application created by Mohammed Imthiyas.</p><p className="lead">ChemSphere is an educational playground for exploring the structure and behavior of matter. It combines local reference data with transparent, browser-side calculations so the reasoning stays visible.</p><div className="about-grid"><div><h3>What’s inside</h3><p>Compound reference cards, equation balancing for supported syntax, common chemistry calculators, an interactive periodic table and molecular geometry explainers.</p></div><div><h3>Built with care</h3><p>Next.js, TypeScript, React and accessible interface patterns. Sample data lives locally and is intentionally labeled for educational use.</p></div><div><h3>A note on safety</h3><p>This application is for learning only. It is not a substitute for laboratory safety procedures, professional chemical analysis or expert supervision.</p></div></div></section>}
